import { useEffect, useRef, useState } from 'react';

/**
 * useIntersectionObserver — Detect when an element enters/exits the viewport.
 * Perfect for: lazy loading, infinite scroll, animations on scroll.
 *
 * @example
 * const { ref, isIntersecting } = useIntersectionObserver({ threshold: 0.1 });
 * <div ref={ref}>{isIntersecting ? 'Visible!' : 'Hidden'}</div>
 */
export function useIntersectionObserver(options?: IntersectionObserverInit) {
  const ref = useRef<HTMLElement | null>(null);
  const [isIntersecting, setIsIntersecting] = useState(false);
  const [hasIntersected, setHasIntersected] = useState(false);

  useEffect(() => {
    const element = ref.current;
    if (!element) return;

    const observer = new IntersectionObserver(([entry]) => {
      setIsIntersecting(entry.isIntersecting);
      if (entry.isIntersecting) setHasIntersected(true);
    }, options);

    observer.observe(element);
    return () => observer.disconnect();
  }, [options?.threshold, options?.rootMargin]);

  return { ref, isIntersecting, hasIntersected };
}

// Usage: Lazy load images
export function LazyImage({ src, alt }: { src: string; alt: string }) {
  const { ref, hasIntersected } = useIntersectionObserver({ threshold: 0.01 });
  return (
    <img
      ref={ref as React.RefObject<HTMLImageElement>}
      src={hasIntersected ? src : undefined}
      alt={alt}
      loading="lazy"
    />
  );
}

/**
 * Redis Cache Wrapper — Drop-in caching layer for expensive operations.
 * Uses cache-aside pattern with TTL and automatic JSON serialization.
 */

const Redis = require('ioredis');

const redis = new Redis(process.env.REDIS_URL || 'redis://localhost:6379');

const DEFAULT_TTL = 300; // 5 minutes

/**
 * Get from cache or compute and store.
 * @param {string} key - Cache key
 * @param {Function} fetchFn - Async function to fetch data on cache miss
 * @param {number} ttl - TTL in seconds
 */
async function getOrSet(key, fetchFn, ttl = DEFAULT_TTL) {
  const cached = await redis.get(key);
  if (cached !== null) {
    return JSON.parse(cached);
  }

  const data = await fetchFn();
  await redis.setex(key, ttl, JSON.stringify(data));
  return data;
}

async function invalidate(key) {
  await redis.del(key);
}

async function invalidatePattern(pattern) {
  const keys = await redis.keys(pattern);
  if (keys.length > 0) await redis.del(...keys);
}

