/**
 * Generic Repository Pattern — TypeScript
 * Abstracts data access layer, making it easy to swap databases.
 */

interface Entity {
  id: number | string;
}

interface Repository<T extends Entity> {
  findById(id: T['id']): Promise<T | null>;
  findAll(filter?: Partial<T>): Promise<T[]>;
  create(data: Omit<T, 'id'>): Promise<T>;
  update(id: T['id'], data: Partial<Omit<T, 'id'>>): Promise<T | null>;
  delete(id: T['id']): Promise<boolean>;
}

// In-memory implementation (for testing/prototyping)
class InMemoryRepository<T extends Entity> implements Repository<T> {
  private store = new Map<T['id'], T>();
  private nextId = 1;

  async findById(id: T['id']): Promise<T | null> {
    return this.store.get(id) ?? null;
  }

  async findAll(filter?: Partial<T>): Promise<T[]> {
    const items = Array.from(this.store.values());
    if (!filter) return items;
    return items.filter(item =>
      Object.entries(filter).every(([k, v]) => (item as any)[k] === v)
    );
  }

  async create(data: Omit<T, 'id'>): Promise<T> {
    const item = { ...data, id: this.nextId++ } as T;
    this.store.set(item.id, item);
    return item;
  }

  async update(id: T['id'], data: Partial<Omit<T, 'id'>>): Promise<T | null> {
    const item = this.store.get(id);
    if (!item) return null;
    const updated = { ...item, ...data };
    this.store.set(id, updated);
    return updated;
  }

  async delete(id: T['id']): Promise<boolean> {
    return this.store.delete(id);
  }
}

// Usage
interface User extends Entity { name: string; email: string; role: string; }

const userRepo = new InMemoryRepository<User>();

(async () => {
  const user = await userRepo.create({ name: 'Alice', email: 'alice@example.com', role: 'admin' });
  console.log(await userRepo.findById(user.id));   // Alice
  await userRepo.update(user.id, { role: 'user' });
  console.log(await userRepo.findAll({ role: 'user' })); // [Alice as user]
})();

export { Repository, InMemoryRepository };

import React, { useReducer, createContext, useContext } from 'react';

/**
 * useReducer Pattern — Scalable state management for complex components.
 * Use when: multiple related state values, complex transitions, testing.
 */

// --- Types ---
type CartItem = { id: number; name: string; price: number; qty: number };
type CartState = { items: CartItem[]; total: number; coupon: string | null };
type CartAction =
  | { type: 'ADD_ITEM'; payload: Omit<CartItem, 'qty'> }
  | { type: 'REMOVE_ITEM'; payload: number }
  | { type: 'UPDATE_QTY'; payload: { id: number; qty: number } }
  | { type: 'APPLY_COUPON'; payload: string }
  | { type: 'CLEAR' };

// --- Reducer (pure function, easy to test) ---
function cartReducer(state: CartState, action: CartAction): CartState {
  switch (action.type) {
    case 'ADD_ITEM': {
      const existing = state.items.find(i => i.id === action.payload.id);
      const items = existing
        ? state.items.map(i => i.id === action.payload.id ? { ...i, qty: i.qty + 1 } : i)
        : [...state.items, { ...action.payload, qty: 1 }];
      return { ...state, items, total: items.reduce((s, i) => s + i.price * i.qty, 0) };
    }
    case 'REMOVE_ITEM': {
      const items = state.items.filter(i => i.id !== action.payload);
      return { ...state, items, total: items.reduce((s, i) => s + i.price * i.qty, 0) };
    }
    case 'UPDATE_QTY': {
      const items = state.items.map(i =>
        i.id === action.payload.id ? { ...i, qty: action.payload.qty } : i
      ).filter(i => i.qty > 0);
      return { ...state, items, total: items.reduce((s, i) => s + i.price * i.qty, 0) };
    }
    case 'APPLY_COUPON': return { ...state, coupon: action.payload };
    case 'CLEAR': return { items: [], total: 0, coupon: null };
    default: return state;
  }
}

// --- Context ---
const CartContext = createContext<{ state: CartState; dispatch: React.Dispatch<CartAction> } | null>(null);

export function CartProvider({ children }: { children: React.ReactNode }) {
  const [state, dispatch] = useReducer(cartReducer, { items: [], total: 0, coupon: null });
  return <CartContext.Provider value={{ state, dispatch }}>{children}</CartContext.Provider>;
}

export function useCart() {
  const ctx = useContext(CartContext);
  if (!ctx) throw new Error('useCart must be used within CartProvider');
  return ctx;
}
